const grouped = {};

for (const row of items.map(i => i.json)) {
  if (!grouped[row.table_name]) {
    grouped[row.table_name] = [];
  }
  grouped[row.table_name].push(`${row.column_name} (${row.data_type}, nullable: ${row.is_nullable})`);
}

let docText = '📘 Database Documentation\n\n';

for (const [table, cols] of Object.entries(grouped)) {
  docText += `Table: ${table}\n- ${cols.join("\n- ")}\n\n`;
}

return [{ json: {}, binary: { data: { data: Buffer.from(docText).toString('base64'), mimeType: 'text/plain', fileName: 'db_documentation.txt' } } }];
